package com.crosscheck.controller;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.AuthService;import org.springframework.web.bind.annotation.*;import java.time.format.DateTimeFormatter;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final CandidateRepository repo;private final AuthService auth;public DashboardController(CandidateRepository r,AuthService a){repo=r;auth=a;}@GetMapping public Map<String,Object> data(@RequestHeader(value="Authorization",required=false)String h){auth.require(h);List<Candidate> cs=repo.findAllByOrderByCreatedAtDesc();long low=cs.stream().filter(c->"LOW".equals(c.getRiskLevel())).count(),med=cs.stream().filter(c->"MEDIUM".equals(c.getRiskLevel())).count(),high=cs.stream().filter(c->"HIGH".equals(c.getRiskLevel())).count(),verified=cs.stream().filter(c->"VERIFIED".equals(c.getVerificationStatus())).count(),pending=cs.size()-verified;List<Map<String,Object>> recent=cs.stream().limit(6).map(c->Map.<String,Object>of("id",c.getId(),"name",c.getName(),"position",c.getPosition(),"riskScore",c.getRiskScore(),"riskLevel",c.getRiskLevel()+" Risk","joiningProbability",c.getJoiningProbability(),"date",c.getCreatedAt().format(DateTimeFormatter.ofPattern("dd MMM yyyy")))).toList();return Map.of("totalCandidates",cs.size(),"offersAnalysed",cs.stream().mapToInt(Candidate::getActiveOffers).sum()+cs.size(),"highRiskCandidates",high,"hiringSuccessRate",cs.isEmpty()?0:Math.round(cs.stream().mapToInt(Candidate::getJoiningProbability).average().orElse(0)),"riskDistribution",List.of(Map.of("name","Low Risk","value",low),Map.of("name","Medium Risk","value",med),Map.of("name","High Risk","value",high)),"joiningTrend",List.of(Map.of("month","Jan","value",62),Map.of("month","Feb","value",71),Map.of("month","Mar","value",69),Map.of("month","Apr","value",84),Map.of("month","May","value",88),Map.of("month","Jun","value",91)),"monthlyHiring",List.of(Map.of("month","Jan","value",5),Map.of("month","Feb","value",8),Map.of("month","Mar","value",6),Map.of("month","Apr","value",11),Map.of("month","May","value",13),Map.of("month","Jun","value",15)),"verificationStatus",List.of(Map.of("name","Verified","value",verified),Map.of("name","Pending","value",pending)),"recentCandidates",recent);}}
